// Expand each uploaded file into its own item with the binary under a single key 'data'
const results = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  for (const key of Object.keys(bin)) {
    results.push({
      json: { ...item.json, sourceBinaryKey: key, fileName: bin[key].fileName || key },
      binary: { data: bin[key] },
    });
  }
}
return results;

const results = [];

const allAppointments = [];
const allPatients = [];
const allDoctors = [];

// Collect data from ALL LLM output items
for (const item of $input.all()) {
  const output = item.json.output || {};

  if (Array.isArray(output.appointments)) {
    allAppointments.push(...output.appointments);
  }

  if (Array.isArray(output.patients)) {
    allPatients.push(...output.patients);
  }

  if (Array.isArray(output.doctors)) {
    allDoctors.push(...output.doctors);
  }
}

// Process ONLY patients who have an appointment
for (const appointment of allAppointments) {

  const patient = allPatients.find(
    p =>
      String(p.patient_id || '').trim() ===
      String(appointment.patient_id || '').trim()
  );

  const doctor = allDoctors.find(
    d =>
      String(d.doctor_id || '').trim() ===
      String(appointment.doctor_id || '').trim()
  );

  // The uploaded file may contain appointment rows without patient rows.
  // Continue processing for Calendar; email is sent only when patient_email is available.

  const rawDate = String(appointment.date || '').trim();
  const rawTime = String(appointment.time || '').trim();

  let dt = DateTime.fromFormat(
    `${rawDate} ${rawTime}`,
    'yyyy-M-d h:mm a',
    { zone: 'Asia/Manila' }
  );

  // Try 24-hour format
  if (!dt.isValid) {
    dt = DateTime.fromFormat(
      `${rawDate} ${rawTime}`,
      'yyyy-M-d H:mm',
      { zone: 'Asia/Manila' }
    );
  }

  let formattedDate = rawDate;
  let formattedTime = rawTime;
  let startIso = null;
  let endIso = null;
  let dateValid = false;

  if (dt.isValid) {
    formattedDate = dt.toFormat('MMMM d, yyyy');
    formattedTime = dt.toFormat('h:mm a');

    startIso = dt.toISO();
    endIso = dt.plus({ hours: 1 }).toISO();

    dateValid = true;
  }

  const doctorName = doctor?.name || 'N/A';
  const specialization = doctor?.specialization || 'N/A';

  const appointmentDetails = `Patient ID: ${appointment.patient_id || 'N/A'}
Doctor: ${doctorName}
Specialization: ${specialization}
Date: ${formattedDate}
Time: ${formattedTime}
Purpose: ${appointment.purpose || 'N/A'}
Status: ${appointment.status || 'N/A'}

📍 Clinic: ${appointment.clinic_id || 'N/A'}`;

  results.push({
    json: {
      clinic_id: appointment.clinic_id,
      patient_id: appointment.patient_id,
      doctor_id: appointment.doctor_id,
      date: appointment.date,
      time: appointment.time,
      purpose: appointment.purpose,
      status: appointment.status,

      patient_name: patient?.name || appointment.patient_id || 'Patient',
      patient_email: patient?.email || '',

      doctor_name: doctorName,
      specialization: specialization,

      formatted_date: formattedDate,
      formatted_time: formattedTime,

      start_iso: startIso,
      end_iso: endIso,

      date_valid: dateValid,

      appointment_details: appointmentDetails
    }
  });
}

return results;

